def IsLocalSignedIndex (f : PiolaSpace n → PiolaSpace n)
    (a b c : PiolaSpace n) (D : ℤ) : Prop :=
  ∃ r > 0, ∀ᵐ y, y ∈ ball c r → signedFiberCount f (fderiv ℝ f) (Icc a b) y = D

