theorem IsLocalSignedIndex.unique {f : PiolaSpace n → PiolaSpace n}
    {a b c : PiolaSpace n} {D D' : ℤ}
    (hD : IsLocalSignedIndex f a b c D) (hD' : IsLocalSignedIndex f a b c D') : D = D'
